<?php
declare(strict_types=1);
$configFile=dirname(__DIR__).'/config.php';
if(!is_file($configFile)){http_response_code(500);exit('ابتدا config.php را تنظیم کنید.');}
$c=require $configFile;
if(empty($_SESSION['chart_admin'])){header('Location: index.php?route=accounts');exit;}
header('X-Content-Type-Options: nosniff');header('Referrer-Policy: same-origin');header('Cache-Control: no-store, private');
$db=new PDO("mysql:host={$c['host']};dbname={$c['database']};charset=utf8mb4",$c['username'],$c['password'],[
 PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC
]);
$db->exec("CREATE TABLE IF NOT EXISTS payment_documents (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, document_type ENUM('receivable','payable') NOT NULL, cheque_number VARCHAR(100) NOT NULL DEFAULT '', due_date DATE NOT NULL, party_name VARCHAR(190) NOT NULL DEFAULT '', bank_name VARCHAR(190) NOT NULL DEFAULT '', amount DECIMAL(15,2) NOT NULL, status ENUM('pending','deposited','paid','returned','cancelled') NOT NULL DEFAULT 'pending', notes VARCHAR(500) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_payment_due_status (due_date,status), INDEX idx_payment_cheque (cheque_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->exec("CREATE TABLE IF NOT EXISTS bank_statement_lines (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, statement_date DATE NOT NULL, description VARCHAR(255) NOT NULL DEFAULT '', reference_no VARCHAR(100) NOT NULL DEFAULT '', amount DECIMAL(15,2) NOT NULL, match_status ENUM('unmatched','matched') NOT NULL DEFAULT 'unmatched', matched_journal_line_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_bank_date_amount (statement_date,amount), INDEX idx_bank_match (match_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->exec("CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(190) NOT NULL, phone VARCHAR(60) NOT NULL DEFAULT '', address VARCHAR(500) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_customers_name (full_name), INDEX idx_customers_phone (phone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->exec("CREATE TABLE IF NOT EXISTS product_price_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, old_price DECIMAL(15,2) NOT NULL, new_price DECIMAL(15,2) NOT NULL, changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reason VARCHAR(255) NOT NULL DEFAULT 'تغییر قیمت هنگام فروش', INDEX idx_price_product_date (product_id,changed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$txnCols=[];foreach($db->query('SHOW COLUMNS FROM transactions')->fetchAll() as $col)$txnCols[$col['Field']]=true;
if(!isset($txnCols['discount_percent']))$db->exec('ALTER TABLE transactions ADD COLUMN discount_percent DECIMAL(7,3) NOT NULL DEFAULT 0');
if(!isset($txnCols['discount_total']))$db->exec('ALTER TABLE transactions ADD COLUMN discount_total DECIMAL(15,2) NOT NULL DEFAULT 0');
if(!isset($txnCols['customer_id']))$db->exec('ALTER TABLE transactions ADD COLUMN customer_id BIGINT UNSIGNED NULL, ADD INDEX idx_transactions_customer_date (customer_id,txn_date)');


require dirname(__DIR__) . '/app/Models/ChartOfAccounts.php';
ensureChartOfAccounts($db);
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$report=$_GET['report']??'journal';
$from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-m-d');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to){http_response_code(400);exit('بازه تاریخ نامعتبر است.');}
$customersForFilter=$db->query('SELECT id,full_name FROM customers ORDER BY full_name')->fetchAll();$productsForFilter=$db->query('SELECT id,name FROM products ORDER BY name')->fetchAll();
$settings=$db->query('SELECT * FROM settings WHERE id=1')->fetch()?:['business_name'=>'کسب‌وکار من','currency'=>'تومان','company_address'=>'','phone'=>'','email'=>'','logo_path'=>'','header_text'=>''];
$rows=[];$title='دفتر روزنامه';
if($report==='daily'){
 $title='خلاصه سود روزانه';
 $q=$db->prepare("SELECT txn_date, SUM(CASE WHEN txn_type='purchase' THEN total ELSE 0 END) purchase_amount, SUM(CASE WHEN txn_type='sale' THEN total ELSE 0 END) sale_amount, SUM(CASE WHEN txn_type='sale' THEN cost_total ELSE 0 END) cost_amount, SUM(CASE WHEN txn_type='sale' THEN total-cost_total ELSE 0 END) gross_profit, COUNT(*) record_count FROM transactions WHERE txn_date BETWEEN ? AND ? GROUP BY txn_date ORDER BY txn_date");
 $q->execute([$from,$to]);$rows=$q->fetchAll();
}elseif($report==='documents'){
 $title='اسناد دریافتنی و پرداختنی';
 $q=$db->prepare('SELECT id,document_type,cheque_number,due_date,party_name,bank_name,amount,status,notes FROM payment_documents WHERE due_date BETWEEN ? AND ? ORDER BY due_date,id');$q->execute([$from,$to]);$rows=$q->fetchAll();
}elseif($report==='bank-reconciliation'){
 $title='گزارش مغایرت‌گیری بانکی';
 $q=$db->prepare("SELECT b.id,b.statement_date,b.description,b.reference_no,b.amount,b.match_status,(SELECT MIN(l.id) FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN accounts a ON a.id=l.account_id WHERE e.entry_date=b.statement_date AND ROUND(l.debit-l.credit,2)=ROUND(b.amount,2) AND (a.title LIKE '%بانک%' OR a.title LIKE '%صندوق%' OR a.title LIKE '%bank%' OR a.title LIKE '%cash%') AND NOT EXISTS (SELECT 1 FROM bank_statement_lines b2 WHERE b2.matched_journal_line_id=l.id AND b2.id<>b.id)) candidate_line_id FROM bank_statement_lines b WHERE b.statement_date BETWEEN ? AND ? ORDER BY b.statement_date,b.id");$q->execute([$from,$to]);$rows=$q->fetchAll();
}elseif($report==='customer-directory'){
 $title='فهرست مشتریان CRM';
 $q=$db->query('SELECT id,full_name,phone,email,address,notes,created_at FROM customers ORDER BY full_name');$rows=$q->fetchAll();
}elseif($report==='customer-sales'){
 $title='گزارش فروش بر اساس مشتری و کالا';
 $customerFilter=(int)($_GET['customer_id']??0);$productFilter=(int)($_GET['product_id']??0);
 $sql="SELECT t.id,t.txn_date,c.full_name customer_name,c.phone,c.address,p.name product,t.quantity,t.unit_price,t.discount_percent,t.discount_total,t.total,t.party_name FROM transactions t JOIN products p ON p.id=t.product_id LEFT JOIN customers c ON c.id=t.customer_id WHERE t.txn_type='sale' AND t.txn_date BETWEEN ? AND ?";
 $args=[$from,$to];if($customerFilter>0){$sql.=" AND t.customer_id=?";$args[]=$customerFilter;}if($productFilter>0){$sql.=" AND t.product_id=?";$args[]=$productFilter;}
 $sql.=" ORDER BY c.full_name,p.name,t.txn_date,t.id";$q=$db->prepare($sql);$q->execute($args);$rows=$q->fetchAll();
}elseif($report==='price-history'){
 $title='تاریخچه تغییر قیمت کالا';
 $q=$db->prepare('SELECT h.id,h.changed_at,p.name product,h.old_price,h.new_price,h.reason FROM product_price_history h JOIN products p ON p.id=h.product_id WHERE DATE(h.changed_at) BETWEEN ? AND ? ORDER BY h.changed_at DESC,h.id DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();
}elseif($report==='trial'){
 $title='تراز آزمایشی';
 $q=$db->prepare('SELECT a.code,a.title,COALESCE(SUM(CASE WHEN e.id IS NOT NULL THEN l.debit ELSE 0 END),0) debit,COALESCE(SUM(CASE WHEN e.id IS NOT NULL THEN l.credit ELSE 0 END),0) credit FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journal_entries e ON e.id=l.entry_id AND e.entry_date BETWEEN ? AND ? WHERE a.is_postable=1 GROUP BY a.id ORDER BY a.code');$q->execute([$from,$to]);$rows=$q->fetchAll();
}elseif($report==='transactions'){
 $title='گزارش خرید و فروش';
 $q=$db->prepare('SELECT t.id,t.txn_date,t.txn_type,p.name product,t.quantity,t.unit_price,t.discount_percent,t.discount_total,t.total,t.payment_method,t.party_name,c.phone customer_phone FROM transactions t JOIN products p ON p.id=t.product_id LEFT JOIN customers c ON c.id=t.customer_id WHERE t.txn_date BETWEEN ? AND ? ORDER BY t.txn_date,t.id');$q->execute([$from,$to]);$rows=$q->fetchAll();
}else{
 $q=$db->prepare('SELECT e.id,e.entry_date,e.description,e.source_type,a.code,a.title,l.debit,l.credit FROM journal_entries e JOIN journal_lines l ON l.entry_id=e.id JOIN accounts a ON a.id=l.account_id WHERE e.entry_date BETWEEN ? AND ? ORDER BY e.entry_date,e.id,l.id');$q->execute([$from,$to]);$rows=$q->fetchAll();
}
if(($_GET['format']??'')==='csv'){
 $filename='report-'.$report.'-'.$from.'-'.$to.'.csv';
 header('Content-Type: text/csv; charset=UTF-8');
 header('Content-Disposition: attachment; filename="'.$filename.'"');
 header('X-Content-Type-Options: nosniff');
 $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
 $safe=static function($v){$v=(string)$v;return preg_match('/^[=+@\\-\\t\\r]/',$v)?"'".$v:$v;};
 if($report==='documents'){fputcsv($out,['شناسه','نوع سند','شماره چک','سررسید','طرف حساب','بانک','مبلغ','وضعیت','توضیحات']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['document_type']==='receivable'?'دریافتنی':'پرداختنی',$x['cheque_number'],$x['due_date'],$x['party_name'],$x['bank_name'],$x['amount'],$x['status'],$x['notes']]));}
 elseif($report==='bank-reconciliation'){fputcsv($out,['شناسه','تاریخ بانک','شرح','شماره مرجع','مبلغ بانک','وضعیت ثبت','ردیف پیشنهادی دفتر']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['statement_date'],$x['description'],$x['reference_no'],$x['amount'],$x['match_status']==='matched'?'تطبیق خودکار پیشنهادی':($x['candidate_line_id']?'دارای تطبیق احتمالی':'بدون تطبیق'),$x['candidate_line_id']??'']));}
 elseif($report==='daily'){fputcsv($out,['تاریخ','جمع خرید','جمع فروش','بهای تمام‌شده فروش','سود ناخالص','تعداد عملیات']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['txn_date'],$x['purchase_amount'],$x['sale_amount'],$x['cost_amount'],$x['gross_profit'],$x['record_count']]));}
 elseif($report==='trial'){fputcsv($out,['کد حساب','نام حساب','بدهکار','بستانکار']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['code'],$x['title'],$x['debit'],$x['credit']]));}
 elseif($report==='transactions'){fputcsv($out,['شماره','تاریخ','نوع','کالا','تعداد','قیمت واحد','درصد تخفیف','مبلغ تخفیف','مبلغ نهایی','پرداخت','طرف حساب','تلفن مشتری']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['txn_date'],$x['txn_type']==='sale'?'فروش':'خرید',$x['product'],$x['quantity'],$x['unit_price'],$x['discount_percent'],$x['discount_total'],$x['total'],$x['payment_method']==='cash'?'نقدی':'نسیه',$x['party_name'],$x['customer_phone']]));}
 elseif($report==='customer-directory'){fputcsv($out,['شناسه','نام مشتری','تلفن','ایمیل','نشانی','یادداشت','تاریخ ثبت']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['full_name'],$x['phone'],$x['email'],$x['address'],$x['notes'],$x['created_at']]));}
 elseif($report==='customer-sales'){fputcsv($out,['شماره','تاریخ','مشتری','تلفن','نشانی','کالا','تعداد','قیمت واحد','درصد تخفیف','مبلغ تخفیف','مبلغ نهایی']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['txn_date'],$x['customer_name']?:$x['party_name'],$x['phone']??'',$x['address']??'',$x['product'],$x['quantity'],$x['unit_price'],$x['discount_percent'],$x['discount_total'],$x['total']]));}
 elseif($report==='price-history'){fputcsv($out,['شناسه','زمان تغییر','کالا','قیمت قبل','قیمت جدید','علت']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['changed_at'],$x['product'],$x['old_price'],$x['new_price'],$x['reason']]));}
 else{fputcsv($out,['شماره سند','تاریخ','شرح','کد حساب','حساب','بدهکار','بستانکار']);foreach($rows as $x)fputcsv($out,array_map($safe,[$x['id'],$x['entry_date'],$x['description'],$x['code'],$x['title'],$x['debit'],$x['credit']]));}
 fclose($out);exit;
}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?></title>
<link rel="stylesheet" href="assets/css/app.css">\n<style>\n.back-to-main-menu{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 18px;margin:8px 0;background:#174ea6;color:#fff!important;border-radius:8px;text-decoration:none;font-weight:700;border:1px solid #174ea6}.back-to-main-menu:hover{filter:brightness(.92)}@media print{.back-to-main-menu{display:none!important}}\n</style>\n<link rel="manifest" href="manifest.webmanifest"><meta name="theme-color" content="#174ea6"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="حسابداری"><script src="assets/js/pwa.js" defer></script></head><body><main>
<section class="no-print"><h2>مرکز چاپ و گزارش‌ها</h2><form method="get"><input type="hidden" name="route" value="print"><label>نوع گزارش <select name="report"><option value="documents" <?= $report==='documents'?'selected':'' ?>>اسناد دریافتنی/پرداختنی</option><option value="bank-reconciliation" <?= $report==='bank-reconciliation'?'selected':'' ?>>مغایرت‌گیری بانکی</option><option value="daily" <?= $report==='daily'?'selected':'' ?>>خلاصه سود روزانه</option><option value="journal" <?=$report==='journal'?'selected':''?>>دفتر روزنامه</option><option value="trial" <?=$report==='trial'?'selected':''?>>تراز آزمایشی</option><option value="transactions" <?=$report==='transactions'?'selected':''?>>خرید و فروش</option><option value="customer-directory" <?= $report==='customer-directory'?'selected':'' ?>>فهرست مشتریان CRM</option><option value="customer-sales" <?=$report==='customer-sales'?'selected':''?>>فروش بر اساس مشتری و کالا</option><option value="price-history" <?=$report==='price-history'?'selected':''?>>تاریخچه قیمت کالا</option></select></label><label>از تاریخ <input type="date" name="from" value="<?=h($from)?>" required></label><label>تا تاریخ <input type="date" name="to" value="<?=h($to)?>" required></label><label>مشتری (برای گزارش مشتری) <select name="customer_id"><option value="0">همه مشتریان</option><?php foreach($customersForFilter as $cf): ?><option value="<?=h($cf['id'])?>" <?=((int)($_GET['customer_id']??0)===(int)$cf['id'])?'selected':''?>><?=h($cf['full_name'])?></option><?php endforeach; ?></select></label><label>کالا (برای گزارش مشتری) <select name="product_id"><option value="0">همه کالاها</option><?php foreach($productsForFilter as $pf): ?><option value="<?=h($pf['id'])?>" <?=((int)($_GET['product_id']??0)===(int)$pf['id'])?'selected':''?>><?=h($pf['name'])?></option><?php endforeach; ?></select></label><button>نمایش گزارش</button></form><div class="actions"><button type="button" onclick="window.print()">چاپ / ذخیره PDF</button><a class="button-link" href="index.php?route=print&amp;report=<?=h($report)?>&amp;from=<?=h($from)?>&amp;to=<?=h($to)?>&amp;customer_id=<?=h($_GET['customer_id']??0)?>&amp;product_id=<?=h($_GET['product_id']??0)?>&amp;format=csv">خروجی اکسل (CSV)</a><a href="index.php?route=data-exchange">ورود اطلاعات از اکسل</a><a class="button-link back-to-main-menu" href="index.php?route=home">← بازگشت به منوی اصلی</a></div></section>
<div class="paper"><div class="head"><div class="letterhead"><?php if(!empty($settings['logo_path'])): ?><img class="letterhead-logo" src="<?=h($settings['logo_path'])?>" alt="آرم شرکت"><?php endif; ?><div class="letterhead-info"><h2><?=h($settings['business_name'])?></h2><?php if(!empty($settings['header_text'])): ?><div><?=h($settings['header_text'])?></div><?php endif; ?><?php if(!empty($settings['company_address'])): ?><div><?=h($settings['company_address'])?></div><?php endif; ?><?php if(!empty($settings['phone'])): ?><div>تلفن: <?=h($settings['phone'])?></div><?php endif; ?><?php if(!empty($settings['email'])): ?><div><?=h($settings['email'])?></div><?php endif; ?></div></div><h2><?=h($settings['business_name'])?></h2><h3><?=h($title)?></h3><div>بازه گزارش: <?=h($from)?> تا <?=h($to)?></div><div class="muted">تاریخ تهیه: <?=date('Y-m-d H:i')?> | واحد پول: <?=h($settings['currency'])?></div></div>
<?php if($report==='documents'):?><table><thead><tr><th>شناسه</th><th>نوع</th><th>شماره چک</th><th>سررسید</th><th>طرف حساب</th><th>بانک</th><th>مبلغ</th><th>وضعیت</th><th>توضیحات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['id'])?></td><td><?=$r['document_type']==='receivable'?'دریافتنی':'پرداختنی'?></td><td><?=h($r['cheque_number'])?></td><td><?=h($r['due_date'])?></td><td><?=h($r['party_name'])?></td><td><?=h($r['bank_name'])?></td><td><?=number_format((float)$r['amount'],2)?></td><td><?=h($r['status'])?></td><td><?=h($r['notes'])?></td></tr><?php endforeach;?></tbody></table>
<?php elseif($report==='bank-reconciliation'):?><p class="report-note">تطبیق این صفحه پیشنهادی و بر اساس تاریخ، مبلغ و حساب‌هایی با عنوان بانک/صندوق است؛ قبل از تأیید باید دستی بررسی شود. در این نسخه، تطبیق احتمالی به معنی مغایرت‌گیری قطعی نیست.</p><table><thead><tr><th>شناسه</th><th>تاریخ</th><th>شرح</th><th>مرجع</th><th>مبلغ</th><th>نتیجه پیشنهادی</th><th>شناسه ردیف دفتر</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['id'])?></td><td><?=h($r['statement_date'])?></td><td><?=h($r['description'])?></td><td><?=h($r['reference_no'])?></td><td><?=number_format((float)$r['amount'],2)?></td><td><?=$r['match_status']==='matched'?'تطبیق خودکار پیشنهادی':($r['candidate_line_id']?'تطبیق احتمالی':'نیازمند بررسی')?></td><td><?=h($r['candidate_line_id']??'')?></td></tr><?php endforeach;?></tbody></table>
<?php elseif($report==='daily'):?><table><thead><tr><th>تاریخ</th><th>جمع خرید</th><th>جمع فروش</th><th>بهای تمام‌شده فروش</th><th>سود ناخالص</th><th>تعداد عملیات</th></tr></thead><tbody><?php $profitSum=0;foreach($rows as $r):$profitSum+=(float)$r['gross_profit'];?><tr><td><?=h($r['txn_date'])?></td><td><?=number_format((float)$r['purchase_amount'],2)?></td><td><?=number_format((float)$r['sale_amount'],2)?></td><td><?=number_format((float)$r['cost_amount'],2)?></td><td><?=number_format((float)$r['gross_profit'],2)?></td><td><?=h($r['record_count'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="4">جمع سود ناخالص</th><th><?=number_format($profitSum,2)?></th><th></th></tr></tfoot></table>
<?php elseif($report==='trial'):?><table><thead><tr><th>کد حساب</th><th>نام حساب</th><th>بدهکار</th><th>بستانکار</th></tr></thead><tbody><?php $td=$tc=0;foreach($rows as $r):$td+=(float)$r['debit'];$tc+=(float)$r['credit'];?><tr><td><?=h($r['code'])?></td><td><?=h($r['title'])?></td><td><?=number_format((float)$r['debit'],2)?></td><td><?=number_format((float)$r['credit'],2)?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="2">جمع</th><th><?=number_format($td,2)?></th><th><?=number_format($tc,2)?></th></tr></tfoot></table>
<?php elseif($report==='customer-directory'):?><table><thead><tr><th>شناسه</th><th>نام مشتری</th><th>تلفن</th><th>ایمیل</th><th>نشانی</th><th>یادداشت</th><th>تاریخ ثبت</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['id'])?></td><td><?=h($r['full_name'])?></td><td><?=h($r['phone'])?></td><td><?=h($r['email'])?></td><td><?=h($r['address'])?></td><td><?=h($r['notes'])?></td><td><?=h($r['created_at'])?></td></tr><?php endforeach;?></tbody></table>
